using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CatalystEffect", menuName = "Data/Battle/Effects/Orion/Catalyst Effect")]
public class CatalystEffect : Effect
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[SerializeField]
	private DefaultEffectAction gainAstriumAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(base.localizationManager.GetLocalizedWhenTriggered(), playerEffectsList.AstriumEffect.GetEffectName(), gainAstriumAction.GetActionDescription((amount == EffectsValues.NO_VALUE) ? (-1) : amount).LowercaseFirst()) + AppendedDescription() + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("Max"), base.MaxEffectAmount);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<PlayerEffects>().AddEffect(gainAstriumAction.Effect, effectAmount);
		return effectAmount;
	}
}
